```Java
  /// <summary>
  /// 计算砍价金额 NewV2版本 - 基于阶梯配置的砍价算法
  /// </summary>
  /// <param name="actInfo">砍价活动信息</param>
  /// <param name="launchRecordInfo">砍价发起记录</param>
  /// <returns>砍价金额</returns>
  public decimal CalculateNewV2(BargainActivityInfo actInfo, BargainLaunchRecordInfo launchRecordInfo = null)
  {
      // 解析阶梯配置
      var steps = FastJsonSerializer.FromJson<List<BargainMultiStepRuleInfo>>(actInfo.StepsJson);
      // 按阶梯索引排序
      steps = steps.OrderBy(s => s.StepIndex).ToList();

      decimal decCutAmount = 0M;
      decimal productPrice = actInfo.Price;
      int currentBargainPersonCount = launchRecordInfo?.BargainPersonCount ?? 0;
      int nextBargainPersonCount = currentBargainPersonCount + 1;

      // 计算当前所在阶梯和阶梯总人数
      int totalPersonCount = 0;
      int currentStepIndex = 0;
      int actualStepIndex = 0;
      BargainMultiStepRuleInfo currentStep = null;
      BargainMultiStepRuleInfo preStep = null;
      int stepStartPersonCount = 0;

      // 计算总人数并定位当前阶梯
      for (int i = 0; i < steps.Count; i++)
      {
          totalPersonCount = steps[i].StepCount;
          if (nextBargainPersonCount <= totalPersonCount)
          {
              currentStepIndex = i;
              currentStep = steps[i];
              actualStepIndex = currentStep.StepIndex;
              break;
          }
      }

      if (currentStep == null) return 0M;
      //stepStartPersonCount = steps.FirstOrDefault(n => n.StepIndex == actualStepIndex)?.StepCount ?? 0;

      // 计算当前阶梯的结束人数
      int stepEndPersonCount = totalPersonCount;

      // 计算当前阶梯的起始价格和目标价格
      decimal stepStartPrice = productPrice;
      // 计算起始价格：减去前面所有阶梯的金额
      if (currentStepIndex >= 1)
      {
          preStep = steps[currentStepIndex - 1];
          stepStartPrice = preStep.StepMoney;
          stepStartPersonCount = preStep.StepCount;
      }
      decimal stepTargetPrice = stepStartPrice - currentStep.StepMoney;

      // 发起砍价活动（第一刀）
      if (launchRecordInfo == null)
      {
          // 第一刀特殊处理
          decimal maxCutAmount = stepStartPrice - stepTargetPrice - (decimal)((totalPersonCount - 1) * 0.01);
          //var coefficient = (decimal)(new Random()).Next(10, 26) / 100; 
          var coefficient = (decimal)(new Random()).Next(15, 31) / 100;
          decCutAmount = maxCutAmount * coefficient;
      }
      // 帮砍人帮砍
      else
      {
          // 计算剩余可砍金额
          //decimal remainingCutAmount = launchRecordInfo.CurrentPrice - stepTargetPrice; 
          decimal remainingCutAmount = launchRecordInfo.CurrentPrice - currentStep.StepMoney;
          int remainingPersonCount = stepEndPersonCount - currentBargainPersonCount;

          // 最后一刀（达到阶梯目标人数或总人数）
          if (nextBargainPersonCount == stepEndPersonCount || nextBargainPersonCount == totalPersonCount)
          {
              decCutAmount = remainingCutAmount;
          }
          // 最后一个阶梯（固定金额分配）
          else if (currentStepIndex == steps.Count - 1)
          {
              // 计算整个最后阶梯的固定金额，确保每个人砍价金额一致，余数放在最后一刀

              // 计算最后一个阶梯的总砍价金额
              decimal lastStepTotalCutAmount = preStep.StepMoney -  currentStep.StepMoney;
              // 计算最后一个阶梯的总人数
              int lastStepTotalPersonCount = currentStep.StepCount - preStep.StepCount;
              // 计算固定金额（精确到分）
              decimal fixedAmountPerPerson = Math.Floor((lastStepTotalCutAmount * 100) / lastStepTotalPersonCount) / 100;

              // 计算当前阶梯已砍人数
              int currentStepPersonCount = nextBargainPersonCount - stepStartPersonCount;

              // 如果是最后一个阶梯的最后一刀，承担余数
              if (currentStepPersonCount == lastStepTotalPersonCount)
              {
                  // 计算前面所有人已砍总金额
                  decimal totalCutByOthers = fixedAmountPerPerson * (lastStepTotalPersonCount - 1);
                  // 最后一刀承担余数
                  decCutAmount = lastStepTotalCutAmount - totalCutByOthers;
              }
              else
              {
                  // 非最后一刀，使用固定金额
                  decCutAmount = fixedAmountPerPerson;
              }
          }
          // 前面的阶梯（随机金额）
          else
          {
              // 计算随机金额范围
              decimal minRandom = 0.01M;
              decimal maxRandom = remainingCutAmount - (decimal)((remainingPersonCount - 1) * 0.01);

              if (maxRandom <= minRandom)
              {
                  decCutAmount = minRandom;
              }
              else
              {
                  // 根据当前砍价人数使用不同的随机系数
                  decimal coefficient;
                  switch (currentBargainPersonCount)
                  {
                      case 1: // 第二刀
                          coefficient = (decimal)(new Random()).Next(15, 31) / 100;
                          break;
                      case 2: // 第三刀
                          coefficient = (decimal)(new Random()).Next(10, 31) / 100;
                          break;
                      default: // 大于三刀
                          var randomMin = 1;
                          var randomMax = (int)Math.Truncate((double)maxRandom * 100.0) + 1;
                          decCutAmount = (decimal)new Random().Next(randomMin, randomMax) / 100;
                          return Math.Max(decCutAmount, 0.01M);
                  }

                  decCutAmount = maxRandom * coefficient;
              }
          }
      }

      // 保留小数后两位
      decCutAmount = (decimal)(Math.Truncate((double)decCutAmount * 100.0) / 100.0);

      // 砍价金额小于0.01取0.01
      if (decCutAmount <= (decimal)0.01)
      {
          decCutAmount = (decimal)0.01;
      }

      return decCutAmount;
  }

